import numpy as np,json
p='/app/runs/step_006_left'; m=json.load(open(p+'/meta.json'))['cameras'];
for cam,pts in [('head_camera',[(125,60),(125,75),(125,90),(100,90),(150,90),(125,105),(140,110)]),('front_camera',[(75,140),(85,140),(95,145),(120,135),(100,120),(85,110),(100,150)])]:
 D=np.load(f'{p}/depth_{cam}.npy')[0].astype(float)/1000;C=np.array(m[cam]['cam2world_gl']);K=np.array(m[cam]['intrinsic_cv']);print(cam)
 for u,v in pts:
  z=D[v,u];pt=C@np.array([(u-160)*z/K[0,0],-(v-120)*z/K[1,1],-z,1]);print(u,v,round(z,3),np.round(pt[:3],3))
